package store
import("context";"crypto/sha256";"encoding/hex";"path/filepath";"testing";"time")
func TestDCVTokenOneTime(t *testing.T){ctx:=context.Background();s,e:=Open(filepath.Join(t.TempDir(),"t.db"));if e!=nil{t.Fatal(e)};defer s.Close();if e=s.Migrate(ctx);e!=nil{t.Fatal(e)};_,e=s.DB.Exec(`INSERT INTO users(id,username,password_hash,role) VALUES(1,'user01','x','user');INSERT INTO instances(id,instance_id,name,dcv_host,dcv_session_id) VALUES(1,'i-1','dev','dev.local','console');INSERT INTO instance_users VALUES(1,1,1);`);if e!=nil{t.Fatal(e)};raw:="secret-token";h:=sha256.Sum256([]byte(raw));hash:=hex.EncodeToString(h[:]);u:=User{ID:1,Username:"user01",Role:"user",Enabled:true};if _,e=s.IssueDCVToken(ctx,u,"i-1",hash,time.Now().Add(time.Minute));e!=nil{t.Fatal(e)};name,ok:=s.ConsumeDCVToken(ctx,hash,"console",time.Now());if !ok||name!="user01"{t.Fatal("first use rejected")};if _,ok=s.ConsumeDCVToken(ctx,hash,"console",time.Now());ok{t.Fatal("token reused")}}
func TestDCVTokenExpired(t *testing.T){ctx:=context.Background();s,_:=Open(filepath.Join(t.TempDir(),"t.db"));defer s.Close();_ = s.Migrate(ctx);_,_=s.DB.Exec(`INSERT INTO users(id,username,password_hash,role) VALUES(1,'u','x','user');INSERT INTO instances(id,instance_id,name,dcv_host) VALUES(1,'i-1','d','d.local');`);h:=sha256.Sum256([]byte("x"));hash:=hex.EncodeToString(h[:]);_,_=s.IssueDCVToken(ctx,User{ID:1},"i-1",hash,time.Now().Add(-time.Second));if _,ok:=s.ConsumeDCVToken(ctx,hash,"console",time.Now());ok{t.Fatal("expired token accepted")}}
